    "code": "G2",
    "summary": "Choose response tools that match the task. A spreadsheet is useful for structured computations; a word processor is useful for explanation and recommendations. An answer must expose the reasoning and assumptions, not just a pasted final number.",
    "steps": [
      "Break the requirement into numbered tasks.",
      "Build clear workings with labels and formulas.",
      "Connect the calculation to a written interpretation and required conclusion."
    ],
    "formula": "Input assumptions → visible workings → result → interpretation.",
    "example": "For a tax comparison, set out separate columns for each alternative, calculate the relevant liabilities and explain the net cash difference. A lower liability alone may omit a different gross cost.",
