  "SBL:I1": {
    "paper": "SBL",
    "code": "I1",
    "summary": "Communication makes technical work usable for its audience. The purpose, audience and requested format determine structure and depth. Explain the recommendation and its basis in plain language while retaining material qualifications.",
    "steps": [
      "Identify the recipient and decision.",
      "Prioritise relevant findings and support them with evidence.",
      "Use the requested format and conclude with proportionate actions."
    ],
    "formula": "Finding → implication → recommendation.",
    "example": "A board memo explains that a project has positive NPV but fails a liquidity constraint. It recommends a financing action or revised timetable rather than reporting the NPV alone.",
    "trap": "Technical accuracy without an understandable conclusion does not meet an advisory brief.",
    "check": "How does advice to a non-specialist differ from a working paper?",
    "answer": "It foregrounds decisions and consequences, defines technical terms and avoids unnecessary calculation detail.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23"
  },
  "SBL:I2": {
    "paper": "SBL",
    "code": "I2",
    "summary": "Commercial acumen connects technical analysis with how an organisation creates value and operates in its environment. Recommendations must be feasible given funding, people, timing, customers and regulatory constraints.",
    "steps": [
      "Identify the business model and strategic objective.",
      "Consider implementation costs, capacity and stakeholder reactions.",
      "Recommend realistic actions with responsibilities and priorities."
    ],
    "formula": "Commercial value depends on net benefits, feasibility, risk and timing.",
    "example": "A tax-efficient restructure saves £10,000 but costs £25,000 to implement and disrupts a key contract. The tax saving alone does not justify the change.",
    "trap": "An academically optimal solution may be commercially infeasible.",
    "check": "Why consider cash timing separately from profitability?",
    "answer": "A profitable option can still fail if the organisation cannot fund the period before benefits arrive.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23"
  },
  "SBL:I3": {
    "paper": "SBL",
    "code": "I3",
    "summary": "Analysis separates a complex situation into relevant drivers; evaluation weighs evidence, alternatives and limitations to reach a justified judgement. Both require application to the scenario rather than a list of textbook models.",
    "steps": [
      "Identify decision criteria and reliable facts.",
      "Compare alternatives consistently, including risk and timing.",
      "State uncertainties and explain why the recommendation remains appropriate."
    ],
    "formula": "Evidence → causal explanation → options → reasoned judgement.",
    "example": "A cheaper supplier has a much higher defect rate. Compare total acquisition, failure and disruption costs before recommending the lowest invoice price.",
    "trap": "A model’s numerical output is only as useful as its assumptions.",
    "check": "What makes a recommendation evaluative?",
    "answer": "It weighs advantages, disadvantages and uncertainty against the stated objectives before choosing an action.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23"
  },
  "SBL:I4": {
    "paper": "SBL",
    "code": "I4",
    "summary": "Professional scepticism means questioning evidence and remaining alert to contradiction or bias without assuming dishonesty. A confident explanation or a convenient estimate should be tested where the consequences are material.",
    "steps": [
      "Identify claims requiring corroboration.",
      "Seek independent evidence and consider alternative explanations.",
      "Explain unresolved uncertainty and its consequence for the decision."
    ],
    "formula": "Trustworthy conclusion = relevant evidence + critical assessment + transparent limits.",
    "example": "Management predicts 20% growth without additional capacity. Challenge the market assumptions and capacity plan rather than accepting a smooth spreadsheet forecast as evidence.",
    "trap": "Scepticism is neither automatic distrust nor refusing to reach a conclusion.",
    "check": "How should contradictory evidence be handled?",
    "answer": "Investigate its source and significance, revise assumptions where needed and disclose material unresolved limitations.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23"
  },
