  "FFM:F1": {
    "paper": "FFM",
    "code": "F1",
    "summary": "Credit management operates within contractual, consumer, insolvency and data-protection constraints. A valid debt and a commercially desirable recovery method are separate questions. Accurate terms and records reduce disputes and support proportionate enforcement.",
    "steps": [
      "Confirm the debtor, contract and payment terms.",
      "Maintain evidence of supply and agreed amendments.",
      "Follow lawful collections and escalation procedures."
    ],
    "formula": "A credit policy must be commercially effective and legally compliant.",
    "example": "A disputed invoice may require correction of delivery evidence before collection action. Repeated demands do not resolve a genuine contractual dispute.",
    "trap": "Aggressive collection does not excuse unlawful disclosure or harassment.",
    "check": "Why agree terms before granting credit?",
    "answer": "They establish price, payment timing and dispute arrangements and reduce uncertainty when collection becomes necessary.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23"
  },
  "FFM:F2": {
    "paper": "FFM",
    "code": "F2",
    "summary": "Credit granting assesses whether a customer can and is likely to pay under proposed terms. Information can include payment history, financial statements, references and external reports. A credit limit controls exposure but must be monitored as orders and payments change.",
    "steps": [
      "Assess risk and expected commercial return.",
      "Set documented limits, terms and approval levels.",
      "Review exceptional orders and changes in creditworthiness."
    ],
    "formula": "Net expected benefit = contribution from sales − financing, administration and expected credit losses.",
    "example": "A profitable new order exceeds the customer’s limit. Management assesses capacity to pay and may request a deposit rather than assume margin alone justifies the exposure.",
    "trap": "Past payment does not guarantee future creditworthiness.",
    "check": "Why review credit limits periodically?",
    "answer": "Customer finances, trading volumes and economic conditions can change the exposure and risk.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23"
  },
  "FFM:F3": {
    "paper": "FFM",
    "code": "F3",
    "summary": "Monitoring receivables identifies overdue amounts, disputes and deteriorating payment behaviour. Ageing analysis is useful but depends on correct due dates and allocations. Combine portfolio measures with customer-specific information.",
    "steps": [
      "Reconcile the receivables ledger and cash allocations.",
      "Review overdue amounts by age, customer and cause.",
      "Escalate significant exposure and update forecasts or allowances."
    ],
    "formula": "Overdue percentage = overdue receivables ÷ total receivables × 100%.",
    "example": "Total receivables are £100,000, including £25,000 overdue. The 25% overdue rate prompts investigation, but £20,000 on one disputed account requires a different response from many small timing delays.",
    "trap": "An improving average collection period can conceal a single large impaired balance.",
    "check": "Why investigate unallocated receipts?",
    "answer": "They can make customers appear overdue and trigger incorrect collection action or misstated balances.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23"
  },
  "FFM:F4": {
    "paper": "FFM",
    "code": "F4",
    "summary": "Debt collection aims to recover cash while controlling cost, legal risk and customer relationships. Escalation should be proportionate to age, amount, dispute status and recoverability. Some debts need negotiation; others need specialist legal or insolvency assessment.",
    "steps": [
      "Verify the debt and contact the customer appropriately.",
      "Agree realistic payment plans where justified and monitor compliance.",
      "Assess escalation costs, security and likely recovery before enforcement."
    ],
    "formula": "Expected net recovery = expected receipts − collection and enforcement costs.",
    "example": "Legal action costing £1,500 to recover a doubtful £1,000 balance is unlikely to be justified solely by that recovery. Other commercial or legal considerations should be explicit.",
    "trap": "A promise to pay is not cash and should not automatically remove impairment concerns.",
    "check": "Why document a repayment agreement?",
    "answer": "It clarifies amounts, dates and consequences and provides evidence if further action is needed.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23"
  },
  "FM:B2": {
    "paper": "FM",
    "code": "B2",
    "summary": "Financial markets connect providers and users of funds and support liquidity and price discovery. Primary markets raise new finance; secondary markets allow existing instruments to trade. Capital and money markets differ mainly by the nature and maturity of instruments.",
    "steps": [
      "Identify the issuer, investor and instrument.",
      "Distinguish new financing from trading existing securities.",
      "Assess intermediary roles and market risks."
    ],
    "formula": "Primary market → new funds to issuer; secondary market → trading between holders.",
    "example": "An investor buying an existing listed share usually pays the selling investor, not the company. A new share issue raises funds for the company subject to issue costs.",
    "trap": "A liquid secondary market supports financing but does not eliminate investment risk.",
    "check": "What role does a financial intermediary perform?",
    "answer": "It connects savers and borrowers and may transform maturity, denomination or risk subject to its own constraints.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23",
    "adaptedFrom": "FFM:C2"
  },
