  "FM:C1": {
    "paper": "FM",
    "code": "C1",
    "summary": "Working capital finances the interval between paying suppliers and receiving customer cash. Inventory, receivables, payables and cash must be managed together. Higher sales can increase funding needs even while reported profit rises.",
    "steps": [
      "Estimate inventory and customer collection periods.",
      "Compare these with supplier credit.",
      "Evaluate liquidity and profitability trade-offs when changing policy."
    ],
    "formula": "Cash operating cycle = inventory days + receivables days − payables days.",
    "example": "Inventory 45 days plus receivables 35 less payables 25 produces a 55-day cash cycle. Reducing collections by 10 days releases funding if bad debts and customer retention do not worsen.",
    "trap": "Supplier credit is financing, not a permanent source of free cash without consequences.",
    "check": "Why can rapid growth create a cash shortage?",
    "answer": "More cash is tied up in inventory and receivables before customers pay.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23",
    "adaptedFrom": "FFM:A1"
  },
  "FM:C2": {
    "paper": "FM",
    "code": "C2",
    "summary": "Receivables policy affects sales, collection costs, bad debts and funding. Payables policy balances supplier credit benefits with discounts, reliability and relationships. Compare incremental effects rather than evaluate one ratio in isolation.",
    "steps": [
      "Assess customer creditworthiness and set limits.",
      "Monitor overdue balances and resolve disputed invoices.",
      "Compare discount cost with funding savings and other relevant benefits."
    ],
    "formula": "Receivables investment ≈ annual credit sales × collection days ÷ 365, under stated assumptions.",
    "example": "Credit sales £730,000 collected in 40 days imply approximately £80,000 receivables. Reducing the period to 30 days releases about £20,000, before changes in sales and other assumptions.",
    "trap": "A longer payment period can indicate disputes or distress rather than efficient financing.",
    "check": "Why might offering a discount be worthwhile?",
    "answer": "The funding, collection and bad-debt savings may exceed its cost, after considering customer behaviour.",
    "scope": "Core topic lesson",
    "reviewStatus": "Editorial review pending",
    "updatedAt": "2026-10-23",
    "adaptedFrom": "FFM:A3"
  },
