    "formula": "Suspicion → investigate appropriately → evaluate evidence → communicate/report under applicable requirements.",
    "example": "Unexpected year-end sales to new counterparties may indicate premature recognition. Inspect delivery, contract terms and subsequent settlement rather than assume every increase is fraudulent.",
    "trap": "An audit is not a guarantee that every unlawful act will be discovered.",
    "check": "Why is management override a concern?",
